sys_script_include.script:
var AppointmentUtils = Class.create();
AppointmentUtils.prototype = {
	initialize: function () {
		this.source = new GlideRecord('u_appointments');
	},

	fetchAppointmentsUsingPatientId: function (patientId) {
		this.source.addQuery('u_patient_id', patientId);
		this.source.query();
		return this.source;
	},

	checkAppStatus: function (appId) {
		this.source.get(appId);
		if (this.source.u_status == 'confirmed') {
			return true;
		}
		else {
			return false;
		}
	},

	fetchAppointmentDetailsById: function (appId) {
		this.source.get(appId);
		var results = {
			app_num: this.source.getValue('number'),
			app_pat_id: this.source.getValue('u_patient_id'),
			app_priority: this.source.getValue('priority'),
			app_date: this.source.getValue('u_appointment_date'),
			app_dept: this.source.getValue('u_department'),
			app_doc: this.source.getValue('u_doctor'),
			app_stat: this.source.getValue('u_status'),
		};

		return results;
	},

	fetchAppointmentsByDate: function (dateStr) {
		var results = [];
		var start = new GlideDateTime(dateStr);
		var end = new GlideDateTime(dateStr);
		end.addDays(1);
		var appointGr4 = new GlideRecord('u_appointments');
		appointGr4.addQuery('u_appointment_date', '>=', start);
		appointGr4.addQuery('u_appointment_date', '<', end);
		appointGr4.query();
		while (appointGr4.next()) {
			results.push({
				number: appointGr4.getDisplayValue('number'),
				patient: appointGr4.getDisplayValue('u_patient_id'),
				date: appointGr4.getDisplayValue('u_appointment_date'),
				department: appointGr4.getDisplayValue('u_department'),
				status: appointGr4.getDisplayValue('u_status'),
				doctor: appointGr4.getDisplayValue('u_doctor')
			});
		}
		return results;
	},

	fetchAppointmentsByDepartment: function (dept) {
        this.source.addEncodedQuery('u_department=' + dept);
		this.source.query();
        return this.source;
	},



	type: 'AppointmentUtils'
};
